DELIMITER //

CREATE PROCEDURE procedure_name

   @param1 datatype,

   @param2 datatype

 BEGIN

   -- SQL_statements to be executed

   SELECT column1, column2

   FROM table_name

   WHERE columnN = @paramN;

END //

DELIMITER;

Example

 DELIMITER //

CREATE PROCEDURE GetCustomersByCity
  @City VARCHAR(50)

 BEGIN
  SELECT * FROM Customers
  WHERE City = @City;
END //

 DELIMITER;

